/**
 * Book catalog: metadata, stock and temporary reservations.
 * See docs/specs/02-catalog-service.md.
 */

export interface CatalogServiceClient {
  /** Public storefront listing (offset pagination, limit <= 100). */

  listBooks(request: ListBooksRequest, metadata?: Metadata): Observable<ListBooksResponse>;

  /** Public substring search on book_name/author + exact genre filter. */

  searchBooks(request: SearchBooksRequest, metadata?: Metadata): Observable<SearchBooksResponse>;

  getBook(request: GetBookRequest, metadata?: Metadata): Observable<GetBookResponse>;

  /** NOT_FOUND if any id is missing (deleted books ARE returned). */

  getBooksByIds(request: GetBooksByIdsRequest, metadata?: Metadata): Observable<GetBooksByIdsResponse>;

  /** EMPLOYER or ADMIN. */

  createBook(request: CreateBookRequest, metadata?: Metadata): Observable<CreateBookResponse>;

  /** EMPLOYER or ADMIN. */

  updateBook(request: UpdateBookRequest, metadata?: Metadata): Observable<UpdateBookResponse>;

  /** ADMIN only — soft delete. */

  deleteBook(request: DeleteBookRequest, metadata?: Metadata): Observable<DeleteBookResponse>;

  /** ADMIN only — clears soft delete. */

  restoreBook(request: RestoreBookRequest, metadata?: Metadata): Observable<RestoreBookResponse>;

  /** Any valid JWT — atomic all-or-nothing reservation with TTL. */

  reserveStock(request: ReserveStockRequest, metadata?: Metadata): Observable<ReserveStockResponse>;

  /** Any valid JWT — idempotent commit (stock decrement). */

  commitStock(request: CommitStockRequest, metadata?: Metadata): Observable<CommitStockResponse>;

  /** Any valid JWT — cancel a reservation. */

  releaseStock(request: ReleaseStockRequest, metadata?: Metadata): Observable<ReleaseStockResponse>;
}

